import numpy as np
import optimizer as opt

best_tot = 2.798940523

for nrows in [5, 6, 7]:
    for ncols in [5, 6, 7]:
        for stagger_type in ['horizontal', 'vertical']:
            for pad_x in np.linspace(0.06, 0.10, 5):
                for pad_y in np.linspace(0.06, 0.10, 5):
                    pts = []
                    dx = (1.0 - 2 * pad_x) / (ncols - 1)
                    dy = (1.0 - 2 * pad_y) / (nrows - 1)
                    for r in range(nrows):
                        for c in range(ncols):
                            if stagger_type == 'horizontal':
                                x = pad_x + c * dx + (0.5 * dx if (r % 2 == 1) else 0.0)
                                y = pad_y + r * dy
                            else:
                                x = pad_x + c * dx
                                y = pad_y + r * dy + (0.5 * dy if (c % 2 == 1) else 0.0)
                            if 0.02 <= x <= 0.98 and 0.02 <= y <= 0.98:
                                if np.hypot(x - opt.KEEPOUT_X, y - opt.KEEPOUT_Y) > opt.KEEPOUT_R + 0.02:
                                    pts.append((x, y))
                    if len(pts) >= opt.N:
                        pts = np.array(pts)
                        # Try first N, last N, center N
                        for selection in ['first', 'last', 'center']:
                            if selection == 'first':
                                centers = pts[:opt.N]
                            elif selection == 'last':
                                centers = pts[-opt.N:]
                            else:
                                cd = np.hypot(pts[:, 0] - 0.5, pts[:, 1] - 0.5)
                                centers = pts[np.argsort(cd)[:opt.N]]
                            val, r_lp, _ = opt.eval_lp(centers)
                            if val > 2.70:
                                circles, tot, succ = opt.run_slsqp(centers, r_init=r_lp*0.999, maxiter=250)
                                ok, tot, msg = opt.check_packing(circles)
                                if ok and tot > best_tot:
                                    best_tot = tot
                                    print(f'NEW RECORD: {best_tot:.9f} ({stagger_type}, {nrows}x{ncols})')
                                    opt.save_if_better(circles, best_tot)
print('Search complete. Best:', best_tot)
"

